<?php

declare(strict_types=1);

namespace JDR\Domain\Maps\Transfer;

defined('JDR_BOOT') || exit;

use JDR\Core\Clock;
use JDR\Core\Db;
use JDR\Core\Errors\ForbiddenException;
use JDR\Core\Errors\NotFoundException;
use JDR\Core\Request;
use JDR\Core\Response;
use JDR\Core\Signer;
use JDR\Domain\Assets\AssetStorage;
use JDR\Domain\Assets\ImageProcessor;
use JDR\Domain\Maps\Map;
use JDR\Domain\Maps\MapPolicy;
use JDR\Domain\Maps\MapRepository;
use JDR\Domain\Users\User;
use JDR\Imaging\ImageRejected;
use JDR\Imaging\Limits;

/**
 * Map thumbnails (contract P4c), generated by the client: PNG or WebP, at most 512 px per side
 * and 512 KB, checked by the image pipeline (Sniffer, structure, script payloads, re-encoding).
 * Stored outside the database: storage/map-thumbs/{ab}/{mapId}-{token}.{png|webp}, path in
 * maps.thumb_asset_path. Served by GET /map-thumbs/{id}?v={token}&e=&s= (signed like the asset
 * files, projet.md 9.3: the URL is only given to the editors of the map). A new thumbnail replaces
 * the previous file; the file leaves with the map (trash purge, orphan sweep for cascades).
 */
final class MapThumbnailService
{
    public const MAX_BYTES = 524288;
    public const MAX_SIDE = 512;
    public const DIR = 'map-thumbs';
    public const ORPHAN_MIN_AGE = 3600;
    private const TYPES = ['image/png' => 'png', 'image/webp' => 'webp'];
    private const PATH_PATTERN = '#^map-thumbs/([0-9a-f]{2})/(\d{1,19})-([0-9a-f]{24})\.(png|webp)$#D';

    public function __construct(
        private Db $db,
        private MapPolicy $policy,
        private MapRepository $maps,
        private ImageProcessor $processor,
        private AssetStorage $storage,
        private Signer $signer,
        private Clock $clock,
    ) {
    }

    /**
     * Rights check of PUT /maps/{id}/thumbnail, before the body is read.
     */
    public function requireEditable(User $user, int $mapId): Map
    {
        return $this->policy->requireEdit($user, $mapId)[0];
    }

    /**
     * Checks the image at $sourcePath (in storage/tmp, always deleted) and makes it the
     * thumbnail of the map.
     *
     * @throws ImageRejected 415 unsupported_type | 413 file_too_large | 422 image_too_large
     */
    public function store(User $user, int $mapId, string $sourcePath): Map
    {
        $map = $this->requireEditable($user, $mapId);
        $work = $this->storage->newWorkDir();
        $final = null;
        try {
            $image = $this->processor->process(
                $sourcePath,
                new Limits(self::MAX_BYTES, self::MAX_SIDE, self::MAX_SIDE * self::MAX_SIDE, 1, 1),
                $work,
            );
            $ext = self::TYPES[$image->mime] ?? null;
            if ($ext === null || $image->isAnimated) {
                throw ImageRejected::unsupportedType('thumbnail_type', 'Map thumbnails are PNG or WebP still images.');
            }
            $token = bin2hex(random_bytes(12));
            $relative = self::DIR . '/' . substr($token, 0, 2) . '/' . $map->id . '-' . $token . '.' . $ext;
            $final = $this->storage->root() . '/' . $relative;
            $this->storage->place($image->path, $final);
            $previous = $this->db->transaction(function () use ($map, $relative): ?string {
                $old = $this->db->fetchValue(
                    'SELECT `thumb_asset_path` FROM ' . $this->db->t('maps') . ' WHERE `id` = ? FOR UPDATE',
                    [$map->id],
                );
                $this->db->execute(
                    'UPDATE ' . $this->db->t('maps') . ' SET `thumb_asset_path` = ? WHERE `id` = ?',
                    [$relative, $map->id],
                );

                return is_string($old) ? $old : null;
            });
            $final = null;
            $this->deleteFile($previous);
        } finally {
            if ($final !== null) {
                @unlink($final);
            }
            $this->storage->remove($work);
            $this->storage->remove($sourcePath);
        }

        return $this->maps->find($map->id) ?? $map;
    }

    /**
     * Signed URL of the thumbnail of a map, null without thumbnail.
     */
    public function url(string $apiBase, Map $map): ?string
    {
        $parts = self::parse($map->thumbAssetPath);
        if ($parts === null || $parts['map_id'] !== $map->id) {
            return null;
        }
        $expires = Signer::dailyExpiry($this->clock->timestamp());
        $signature = $this->signer->signWithExpiry($expires, 'map-thumb', (string) $map->id, $parts['token']);
        $separator = str_contains($apiBase, '?') ? '&' : '?';

        return $apiBase . '/map-thumbs/' . $map->id . $separator
            . http_build_query(['v' => $parts['token'], 'e' => $expires, 's' => $signature]);
    }

    /**
     * GET /map-thumbs/{id}?v=&e=&s= (public: the signed URL is the authorization).
     */
    public function serve(Request $request, int $mapId): Response
    {
        $token = $request->query['v'] ?? null;
        $expires = $request->query['e'] ?? null;
        $signature = $request->query['s'] ?? null;
        if (!is_string($token) || preg_match('/^[0-9a-f]{24}$/D', $token) !== 1
            || !is_string($expires) || !ctype_digit($expires) || strlen($expires) > 12
            || !is_string($signature) || $signature === ''
            || !$this->signer->verifyWithExpiry($signature, (int) $expires, $this->clock->timestamp(), 'map-thumb', (string) $mapId, $token)) {
            throw new ForbiddenException();
        }
        $map = $this->maps->find($mapId);
        $parts = self::parse($map?->thumbAssetPath);
        if ($map === null || $parts === null || $parts['token'] !== $token || $parts['map_id'] !== $mapId) {
            throw new NotFoundException();
        }
        $path = $this->storage->root() . '/' . $map->thumbAssetPath;
        $size = is_file($path) ? filesize($path) : false;
        if ($size === false) {
            throw new NotFoundException();
        }
        $etag = '"' . $token . '"';
        $headers = [
            'Content-Type' => $parts['ext'] === 'png' ? 'image/png' : 'image/webp',
            'ETag' => $etag,
            'Cache-Control' => 'private, max-age=86400, immutable',
            'Content-Disposition' => 'inline; filename="map-' . $mapId . '.' . $parts['ext'] . '"',
            'X-Content-Type-Options' => 'nosniff',
            'Content-Security-Policy' => "default-src 'none'",
        ];
        $ifNoneMatch = $request->header('if-none-match');
        if ($ifNoneMatch !== null && in_array($etag, array_map('trim', explode(',', $ifNoneMatch)), true)) {
            return new Response('', 304, $headers);
        }

        return (new Response('', 200, $headers + ['Content-Length' => (string) $size]))->withFile($path);
    }

    /**
     * Deletes a thumbnail file given its stored relative path (ignored when malformed).
     */
    public function deleteFile(?string $relative): void
    {
        if (self::parse($relative) !== null) {
            @unlink($this->storage->root() . '/' . $relative);
        }
    }

    /**
     * Cron "map_thumbs": deletes the thumbnail files no map references any more (maps purged
     * with their game or account), older than an hour (never a file being written).
     */
    public function purgeOrphans(int $limit = 500): int
    {
        $dir = $this->storage->root() . '/' . self::DIR;
        if (!is_dir($dir)) {
            return 0;
        }
        $referenced = [];
        foreach ($this->db->fetchAll(
            'SELECT `thumb_asset_path` FROM ' . $this->db->t('maps') . ' WHERE `thumb_asset_path` IS NOT NULL',
        ) as $row) {
            $referenced[(string) $row['thumb_asset_path']] = true;
        }
        $count = 0;
        $before = $this->clock->timestamp() - self::ORPHAN_MIN_AGE;
        $items = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($dir, \FilesystemIterator::SKIP_DOTS));
        foreach ($items as $item) {
            if ($count >= $limit) {
                break;
            }
            if (!$item->isFile() || str_starts_with($item->getFilename(), '.') || $item->getFilename() === 'index.php') {
                continue;
            }
            $relative = self::DIR . '/' . basename($item->getPath()) . '/' . $item->getFilename();
            if (!isset($referenced[$relative]) && $item->getMTime() < $before) {
                @unlink($item->getPathname());
                $count++;
            }
        }

        return $count;
    }

    /**
     * @return array{map_id: int, token: string, ext: string}|null
     */
    private static function parse(?string $relative): ?array
    {
        if ($relative === null || preg_match(self::PATH_PATTERN, $relative, $m) !== 1 || $m[1] !== substr($m[3], 0, 2)) {
            return null;
        }

        return ['map_id' => (int) $m[2], 'token' => $m[3], 'ext' => $m[4]];
    }
}
